[tikz]
\begin{tikzpicture}[scale=0.9]
\coordinate (L) at (0,0);
\coordinate (R) at (4.6,0);
\coordinate (T) at (3.209,3.442);
\draw (L)--(R) node[midway,below] {$16\text{ cm}$};
\draw (L)--(T);
\draw (R)--(T) node[midway,right] {$x$};
\pic[draw,"$65^{\circ}$",angle radius=0.5cm,angle eccentricity=1.6] {angle=L--T--R};
\pic[draw,"$47^{\circ}$",angle radius=0.6cm,angle eccentricity=1.5] {angle=R--L--T};
\end{tikzpicture}
[/tikz]
Find the length of $x$, correct to $1$ decimal place.

